#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

const long long MOD1_CONST = 998244353;
const long long MOD2_CONST = 1000000007;

long long readNumber() {
    long long num = 0;
    int sign_flag = 1;
    char ch = getchar();
    while (ch < '0' || ch > '9') {
        if (ch == '-') sign_flag = -1;
        ch = getchar();
    }
    while (ch >= '0' && ch <= '9') {
        num = (num << 1) + (num << 3) + (ch - '0');
        ch = getchar();
    }
    return num * sign_flag;
}

long long total_n_value;
vector<int> buckets_list[10];
long long prefix_sum_list[10];
long long count_total1 = 0, count_total2 = 0, answer_total = 0;
int power_vals[7] = {1, 10, 100, 1000, 10000, 100000, 1000000};

void generate_all(int length, long long val) {
    if (length > 6) return;
    buckets_list[length].push_back((count_total1 - val + MOD1_CONST) % MOD1_CONST);
    prefix_sum_list[length] += (count_total1 - val + MOD1_CONST) % MOD1_CONST;
    ++count_total1;
    for (int digit = 0; digit <= 9; ++digit) {
        generate_all(length + 1, val * 10 + digit);
    }
}

bool is_in_range(long long x) {
    return x * 1000000 + 999999 <= total_n_value && x * 10000000 > total_n_value;
}

void traverse(int length, long long val) {
    if (val > total_n_value) return;
    if (is_in_range(val)) {
        for (int i = 0; i <= 6; ++i) {
            long long v1 = ((count_total2 + 1 - val * power_vals[i]) % MOD1_CONST + MOD1_CONST) % MOD1_CONST;
            int idx = lower_bound(buckets_list[i].begin(), buckets_list[i].end(), (int)(MOD1_CONST - v1)) - buckets_list[i].begin();
            answer_total = (answer_total + (prefix_sum_list[i] + buckets_list[i].size() * v1 - 1LL * MOD1_CONST * (buckets_list[i].size() - idx))) % MOD2_CONST;
        }
        count_total2 += count_total1;
    } else {
        if (length) ++count_total2;
        answer_total = (answer_total + ((count_total2 - val) % MOD1_CONST + MOD1_CONST) % MOD1_CONST) % MOD2_CONST;
        for (int digit = (!length); digit <= 9; ++digit) {
            traverse(length + 1, val * 10 + digit);
        }
    }
}

int main() {
    total_n_value = readNumber();
    generate_all(0, 0);
    for (int i = 0; i <= 6; ++i) {
        sort(buckets_list[i].begin(), buckets_list[i].end());
    }
    traverse(0, 0);
    cout << answer_total << "\n";
    return 0;
}
